<?php
if(!defined('ABSPATH')){exit;}
final class AICS_Internal_Link_Recommendation_Service{
	public function recommend(array $article,array $candidates,int $maximum):array{$maximum=max(0,min(10,$maximum));if(!$maximum){return array();}$hay=$this->terms(($article['seo_focus_keyword']??'').' '.($article['title']??'').' '.wp_strip_all_tags((string)($article['content']??'')));$ranked=array();foreach($candidates as $c){$candidate=$this->terms($c['title'].' '.$c['slug'].' '.implode(' ',$c['terms']));$overlap=array_values(array_intersect($hay,$candidate));$anchor='';foreach($overlap as $term){if(strlen($term)>=4&&preg_match('/(?<![\pL\pN])'.preg_quote($term,'/').'(?![\pL\pN])/iu',(string)$article['content'])){$anchor=$term;break;}}if(''===$anchor){continue;}$ranked[]=array('score'=>count($overlap),'target_post_id'=>$c['post_id'],'verified_url'=>$c['url'],'anchor_text'=>$anchor,'target_title'=>$c['title'],'insertion_context'=>'paragraph','status'=>'recommended','reason'=>'deterministic_relevance');}usort($ranked,static fn($a,$b)=>$b['score']<=>$a['score']);return array_map(static function($r){unset($r['score']);return $r;},array_slice($ranked,0,$maximum));}
	private function terms(string $text):array{$text=function_exists('mb_strtolower')?mb_strtolower(wp_strip_all_tags($text),'UTF-8'):strtolower(wp_strip_all_tags($text));$parts=preg_split('/[^\pL\pN]+/u',$text,-1,PREG_SPLIT_NO_EMPTY)?:array();$stop=array('the','and','for','with','from','that','this','your','into','about','are','was','how','why','what');return array_values(array_unique(array_filter($parts,static fn($w)=>strlen($w)>=3&&!in_array($w,$stop,true))));}
}
